def perform_operation(num1, operator, num2):
    """Perform a mathematical operation based on the given operator."""
    if operator == '+':
        return num1 + num2
    elif operator == '-':
        return num1 - num2
    elif operator == '*':
        return num1 * num2
    elif operator == '/':
        if num2 == 0:
            return "Error: Division by zero is not allowed."
        else:
            return num1 / num2
    else:
        return "Error: Invalid operator. Please use +, -, *, or /."


def main():
    while True:
        try:
            # Get user input
            input_str = input("Enter a mathematical expression (e.g., 10 + 5): ")
            nums = input_str.split()
            num1 = float(nums[0])
            operator = nums[1]
            num2 = float(nums[2])

            # Perform the operation
            result = perform_operation(num1, operator, num2)

            # Print the result
            print(f"{num1} {operator} {num2} = {result}")

            # Ask the user if they want to continue
            continue_input = input("Do you want to perform another operation? (yes/no): ").lower()
            if continue_input != 'yes':
                break

        except ValueError:
            print("Error: Invalid input. Please enter numbers and operators.")


if __name__ == "__main__":
    main()
